--[[ generated by midnight from midnight/resurrect/git.mn, edit that instead ]] local _MODULE = {}

local branch_cmd = {"git", "branch", "--show-current"}


local function parse_branch(code, out)
  if code ~= 0 then return nil end
  local branch = vim.trim(out or "")
  if branch == "" then return nil else return branch end
end

--- the current git branch, or nil (not a repo, or a detached HEAD)
---@return string|nil
function _MODULE.current_branch()
  local out = vim.fn.system(branch_cmd)
  return parse_branch(vim.v.shell_error, out)
end

--- calls cb({ current, new }) when the branch changes. Checks once a second w/
--- an async git call, so the UI never waits on git. Returns the timer (stop
--- and close it to stop watching).
--- TODO: is a timer the best way to do this? (a uv fs_event on .git/HEAD
--- would avoid polling, but .git can be a file in worktrees)
function _MODULE.watch_branch(cb)
  local timer = vim.uv.new_timer()
  local known = _MODULE.current_branch()
  local pending = false
  timer:start(0, 1000, function()
    if pending then return end
    pending = true
    vim.system(branch_cmd, {text = true}, function(res)
      pending = false
      local branch = parse_branch(res.code, res.stdout)

      if branch and branch ~= known then
        local change = {current = known, new = branch}
        known = branch
        vim.schedule(function() return cb(change) end)
      end
    end)
  end)
  return timer
end
return _MODULE
